(let [s @infra.dev.window.lifecycle/service-state w @(:world s) v (ns-resolve 'user 'truth-native-current-frame-observer)] {:pid (.pid (java.lang.ProcessHandle/current)) :observer-exists? (boolean v) :world-identity (System/identityHashCode (:world s)) :window (:window s) :tick (:tick w) :workers [(.isAlive ^Thread (:thread s)) (.isAlive ^Thread (:sim-thread s))] :errors [(:error s) (:ui/error-state @(:config s))] :proc-reads (mapv (fn [path] {:path path :slurp (try (count (slurp path)) (catch Throwable t {:error (str t)})) :buffered-line (try (with-open [r (clojure.java.io/reader path)] (.readLine ^java.io.BufferedReader r)) (catch Throwable t {:error (str t)}))}) ["/proc/sys/kernel/random/boot_id" "/proc/self/stat"])})
